inline const PTLevelGrowth* PTGetLevelGrowth(int profession,int advanced,int level) {
if(level<1)return 0;
if(profession==3 && advanced && level<=90)return &ptGrowth1_3[level-1];
if(profession==3 && !advanced && level<=200)return &ptGrowth0_3[level-1];
if(profession==0 && !!advanced==0 && level<=200)return &ptGrowth0_0[level-1];
if(profession==1 && !!advanced==0 && level<=200)return &ptGrowth0_1[level-1];
if(profession==2 && !!advanced==0 && level<=200)return &ptGrowth0_2[level-1];
if(profession==0 && !!advanced==1 && level<=80)return &ptGrowth1_0[level-1];
if(profession==1 && !!advanced==1 && level<=80)return &ptGrowth1_1[level-1];
if(profession==2 && !!advanced==1 && level<=80)return &ptGrowth1_2[level-1];
return 0;
}
